-- document-import T10: DOCX and PPTX imports.
--
-- 1. import_jobs records the imported format and the images a done job
--    dropped (generated by drizzle-kit from src/shared/db/schema.ts).
--    Existing rows are backfilled from their storage path's extension
--    (`{ownerId}/{uploadId}.{pdf|docx|pptx}`); before this migration the
--    bucket only accepted PDF, so in practice every old row stays 'pdf'.
-- 2. The private `page-pdfs` bucket (0006) accepts the DOCX and PPTX mimes
--    too, same 20 MiB limit. Raw SQL like 0006: drizzle-kit does not
--    introspect the `storage` schema. The bucket keeps its historical name
--    (renaming a bucket means moving every object); known naming debt,
--    documented in src/modules/ingestion/README.md.
ALTER TABLE "import_jobs" ADD COLUMN "format" text DEFAULT 'pdf' NOT NULL;--> statement-breakpoint
ALTER TABLE "import_jobs" ADD COLUMN "skipped_images" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "import_jobs" ADD CONSTRAINT "import_jobs_format_check" CHECK ("import_jobs"."format" in ('pdf', 'docx', 'pptx'));--> statement-breakpoint
ALTER TABLE "import_jobs" ADD CONSTRAINT "import_jobs_skipped_images_check" CHECK ("import_jobs"."skipped_images" >= 0);--> statement-breakpoint
update "import_jobs"
set "format" = lower(substring("storage_path" from '\.(pdf|docx|pptx)$'))
where "storage_path" ~* '\.(pdf|docx|pptx)$';--> statement-breakpoint
update storage.buckets
set file_size_limit = 20971520,
  allowed_mime_types = array[
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation'
  ]
where id = 'page-pdfs';
